def add_wheels(a, b):
    result = []
    for i in range(len(a)):
        result.append(a[i] + b[i])
    return result

unitTests:
@test("no carries")
def _():
    check_eq(add_wheels([2, 3], [4, 5]), [6, 8])

@test("a carry ripples along")
def _():
    check_eq(add_wheels([2, 7, 4], [9, 5]), [1, 3, 5])
    check_eq(add_wheels([9, 9, 9], [1]), [0, 0, 0, 1])

@test("different lengths, either way round")
def _():
    check_eq(add_wheels([5], [5, 9]), [0, 0, 1])
    check_eq(add_wheels([0], [0]), [0])

